if(typeof jQuery=='undefined'){alert("请引用jq框架")};(function($){var tab=function(obj,config){var _this=this;this.loop=0;this.obj=obj;this.timer=null;this.default={"type":"click","effect":"fade","show":1,"auto":false };this.opts=$.extend(true,this.default,config);this.tabNav=this.obj.find('.tab-nav li');this.tabItem=this.obj.find('.tab-wrap .tab-item');if(this.opts.type=="click"){this.tabNav.bind("click",function(){_this.currentChange($(this));})}else{this.tabNav.mouseover(function(){_this.currentChange($(this));})}if(this.default.auto){this.autoPlay(this);this.obj.hover(function(){clearInterval(_this.timer);},function(){_this.autoPlay(_this);})}this.init()};tab.prototype={init:function(){var index=this.opts.show-1;this.loop=index;if(index>this.tabItem.size()-1){index=0}this.tabNav.eq(index).addClass("active").siblings().removeClass("active");this.tabItem.eq(index).addClass("active").siblings().removeClass("active")},currentChange:function(ele){var index=ele.index();ele.addClass("active").siblings().removeClass("active");if(this.opts.effect=="default"){this.tabItem.eq(index).addClass("active").siblings().removeClass("active")}else if(this.opts.effect==="fade"){this.tabItem.eq(index).stop().fadeIn().siblings().stop().fadeOut()}if(this.default.auto){this.loop=index}},autoPlay:function(_this){var size=this.tabItem.size();this.timer=setInterval(function(){_this.loop+=1;if(_this.loop>=size){_this.loop=0}_this.currentChange(_this.tabNav.eq(_this.loop));},this.default.auto)}};$.fn.extend({tab:function(){this.each(function(){new tab($(this))});return this}});window.tab=tab;})(jQuery);